begin;

do $$
declare
  v_actor uuid;
  v_result jsonb;
  v_batch_reference text := 'fusion-covenas-tolu-ebf0cb38d37759a1';
begin
  if exists (
    select 1
    from public.audit_log
    where accion = 'inventario_covenas_fusionado_tolu'
      and detalle->>'source_sha256' = 'ebf0cb38d37759a111accd0df180e54a3438f1c4a36aeeec87628c6958542cb1'
  ) then
    return;
  end if;

  if exists (select 1 from public.stock_cantidad where tienda_codigo = 'CK-11')
     or exists (select 1 from public.unidades where tienda_actual = 'CK-11')
     or exists (select 1 from public.movimientos where tienda_codigo = 'CK-11') then
    raise exception 'Coveñas ya tiene inventario o movimientos; se detiene la fusión para evitar duplicados';
  end if;

  select id into v_actor
  from public.perfiles
  where activo = true
    and rol = 'gerencia'
    and lower(nombre) = 'oscar pacheco'
  order by created_at
  limit 1;

  if v_actor is null then
    raise exception 'No se encontró el perfil activo de Gerencia para registrar la fusión';
  end if;

  perform set_config('request.jwt.claim.sub', v_actor::text, true);

